/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
    const {
        button_action_type,
        button_action_payload,
    } = api.context.props.payload.props_details;

    if (button_action_type === 'event') {
        return {
            eventName: button_action_payload,
            eventPayload: {
                content_block: api.context.props.payload,
                actual_event: event
            }
        };
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var ariaProperties = api.context.props.payload.props_details.aria_properties;
    return ariaProperties?.button;
}

